import{_ as t,o,c as n,ag as a}from"./chunks/framework.BPmc_f4o.js";const m=JSON.parse('{"title":"Scope","description":"What the tecs command deliberately will not do, and how its offline reference shares one content tree with this site","frontmatter":{"description":"What the tecs command deliberately will not do, and how its offline reference shares one content tree with this site","outline":"deep"},"headers":[],"relativePath":"cli/scope.md","filePath":"cli/scope.md"}'),i={name:"cli/scope.md"};function s(r,e,d,c,h,l){return o(),n("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /cli/scope.md for this page in Markdown format</div><h1 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Not built yet</p><p>The <code>tecs</code> command does not exist on this branch. This page records the shape it is planned to take so that nothing else in the site has to pretend it is already there. Everything below is a plan, not a reference, and the commands cannot be run today.</p><p>Build and run through <code>make</code> in the meantime. See <a href="/getting-started.html">getting started</a>.</p></div><h2 id="what-it-will-not-do" tabindex="-1">What it will not do <a class="header-anchor" href="#what-it-will-not-do" aria-label="Permalink to &quot;What it will not do&quot;">​</a></h2><p><strong>It does not wrap CMake or Make.</strong> CMake and Make build the engine and the tool. The tool builds games. Those are different jobs with different inputs, so there is no second implementation and no shelling out to Make from a user&#39;s machine. <code>make run</code> runs this repository&#39;s own demo, which is a test of the engine; <code>tecs run</code> builds and runs a project. Both stay, and neither delegates to the other.</p><p><strong>It does not cross-compile.</strong> A macOS host cannot produce a Windows game and the reverse is worse, since a Mach-O needs an SDK whose licence forbids redistributing it. <code>tecs dist</code> packages for the platform it is running on, and <code>tecs new</code> scaffolds a CI workflow with a three-OS matrix that runs it on each.</p><h2 id="offline-documentation" tabindex="-1">Offline documentation <a class="header-anchor" href="#offline-documentation" aria-label="Permalink to &quot;Offline documentation&quot;">​</a></h2><p>This site and the tool&#39;s offline reference are meant to be one content tree, not two. Every page here carries a one-line <code>description:</code> in its frontmatter for exactly that reason: the descriptions label pages in the generated <code>llms.txt</code> index and in an offline reference. <code>scripts/check-docs-descriptions.sh</code> gates it, and <code>make docs-check</code> runs it.</p>',8)])])}const f=t(i,[["render",s]]);export{m as __pageData,f as default};
